"use strict";(self.webpackChunkdev_docs=self.webpackChunkdev_docs||[]).push([[1779],{6279(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","href":"/dev-docs/","label":"Yosemite Crew Overview","docId":"overview","unlisted":false},{"type":"category","label":"Guides","collapsed":false,"items":[{"type":"link","href":"/dev-docs/guides/notification-setup","label":"Notification Setup Guide","docId":"guides/notification-setup-guide","unlisted":false},{"type":"link","href":"/dev-docs/guides/backend-chat","label":"Backend Chat Implementation","docId":"guides/backend-chat-implementation","unlisted":false}],"collapsible":true},{"type":"category","label":"Apps","collapsed":false,"items":[{"type":"link","href":"/dev-docs/apps/frontend","label":"Frontend App README","docId":"apps/frontend-app","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend","label":"Backend App README","docId":"apps/backend-app","unlisted":false},{"type":"link","href":"/dev-docs/openapi","label":"OpenAPI Reference","docId":"openapi","unlisted":false},{"type":"category","label":"Backend API","collapsed":true,"items":[{"type":"link","href":"/dev-docs/apps/backend/api","label":"Backend API Index","docId":"apps/backend/backend-index","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/account-withdrawal","label":"Account Withdrawal API","docId":"apps/backend/routers/backend-api-account-withdrawal","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/adverse-event","label":"Adverse Event API","docId":"apps/backend/routers/backend-api-adverse-event","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/appointment","label":"Appointment API","docId":"apps/backend/routers/backend-api-appointment","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/audit-trail","label":"Audit Trail API","docId":"apps/backend/routers/backend-api-audit-trail","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/authUserMobile","label":"Authusermobile API","docId":"apps/backend/routers/backend-api-authUserMobile","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/availability","label":"Availability API","docId":"apps/backend/routers/backend-api-availability","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/chat","label":"Chat API","docId":"apps/backend/routers/backend-api-chat","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/companion-organisation","label":"Companion Organisation API","docId":"apps/backend/routers/backend-api-companion-organisation","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/companion","label":"Companion API","docId":"apps/backend/routers/backend-api-companion","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/contact-us","label":"Contact Us API","docId":"apps/backend/routers/backend-api-contact-us","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/coparentInvite","label":"Coparentinvite API","docId":"apps/backend/routers/backend-api-coparentInvite","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/dashboard","label":"Dashboard API","docId":"apps/backend/routers/backend-api-dashboard","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/deviceToken","label":"Devicetoken API","docId":"apps/backend/routers/backend-api-deviceToken","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/documenso","label":"Documenso API","docId":"apps/backend/routers/backend-api-documenso","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/document","label":"Document API","docId":"apps/backend/routers/backend-api-document","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/expense","label":"Expense API","docId":"apps/backend/routers/backend-api-expense","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/form","label":"Form API","docId":"apps/backend/routers/backend-api-form","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/inventory","label":"Inventory API","docId":"apps/backend/routers/backend-api-inventory","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/invoice","label":"Invoice API","docId":"apps/backend/routers/backend-api-invoice","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/mobile.config","label":"Mobile.Config API","docId":"apps/backend/routers/backend-api-mobile.config","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/notification","label":"Notification API","docId":"apps/backend/routers/backend-api-notification","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/observationTool","label":"Observationtool API","docId":"apps/backend/routers/backend-api-observationTool","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/organisation-document","label":"Organisation Document API","docId":"apps/backend/routers/backend-api-organisation-document","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/organisation-invite","label":"Organisation Invite API","docId":"apps/backend/routers/backend-api-organisation-invite","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/organisation-room","label":"Organisation Room API","docId":"apps/backend/routers/backend-api-organisation-room","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/organisationRating","label":"Organisationrating API","docId":"apps/backend/routers/backend-api-organisationRating","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/organization","label":"Organization API","docId":"apps/backend/routers/backend-api-organization","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/parent-companion","label":"Parent Companion API","docId":"apps/backend/routers/backend-api-parent-companion","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/parent","label":"Parent API","docId":"apps/backend/routers/backend-api-parent","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/service","label":"Service API","docId":"apps/backend/routers/backend-api-service","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/speciality","label":"Speciality API","docId":"apps/backend/routers/backend-api-speciality","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/stripe","label":"Stripe API","docId":"apps/backend/routers/backend-api-stripe","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/task","label":"Task API","docId":"apps/backend/routers/backend-api-task","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/user-organization","label":"User Organization API","docId":"apps/backend/routers/backend-api-user-organization","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/user-profile","label":"User Profile API","docId":"apps/backend/routers/backend-api-user-profile","unlisted":false},{"type":"link","href":"/dev-docs/apps/backend/api/user","label":"User API","docId":"apps/backend/routers/backend-api-user","unlisted":false}],"collapsible":true},{"type":"link","href":"/dev-docs/apps/mobile-app","label":"Mobile App README","docId":"apps/mobile-app","unlisted":false}],"collapsible":true},{"type":"category","label":"UI System","collapsed":false,"items":[{"type":"link","href":"/dev-docs/ui-system/overview","label":"UI System Overview","docId":"ui-system/overview","unlisted":false},{"type":"link","href":"/dev-docs/ui-system/design-tokens","label":"Design Tokens","docId":"ui-system/design-tokens","unlisted":false},{"type":"link","href":"/dev-docs/ui-system/component-taxonomy","label":"Component Taxonomy","docId":"ui-system/component-taxonomy","unlisted":false},{"type":"link","href":"/dev-docs/ui-system/contribution-guide","label":"Contribution Guide","docId":"ui-system/contribution-guide","unlisted":false},{"type":"link","href":"/dev-docs/ui-system/validation-matrix","label":"Validation Matrix","docId":"ui-system/validation-matrix","unlisted":false}],"collapsible":true},{"type":"category","label":"Policies","collapsed":false,"items":[{"type":"link","href":"/dev-docs/policies/contributing","label":"Contributing Guide","docId":"policies/contributing","unlisted":false},{"type":"link","href":"/dev-docs/policies/code-of-conduct","label":"Code of Conduct","docId":"policies/code-of-conduct","unlisted":false},{"type":"link","href":"/dev-docs/policies/security","label":"Security Policy","docId":"policies/security","unlisted":false}],"collapsible":true}]},"docs":{"apps/backend-app":{"id":"apps/backend-app","title":"Backend App README","description":"(Source: apps/backend/README.md)","sidebar":"docs"},"apps/backend/backend-index":{"id":"apps/backend/backend-index","title":"Backend API Index","description":"This index lists the Yosemite Crew backend REST API, split by router (one page per feature area). Base paths reflect the registration in apps/backend/src/routers/index.ts. For how the server itself boots and models data, see the Backend App README.","sidebar":"docs"},"apps/backend/routers/backend-api-account-withdrawal":{"id":"apps/backend/routers/backend-api-account-withdrawal","title":"Account Withdrawal API","description":"Handles account withdrawal (deletion) requests submitted by pet parents from the mobile app. The single endpoint records a signed withdrawal request; it is guarded by the mobile auth middleware (requireMobileAuth).","sidebar":"docs"},"apps/backend/routers/backend-api-adverse-event":{"id":"apps/backend/routers/backend-api-adverse-event","title":"Adverse Event API","description":"Manages adverse event reports (for example, a suspected reaction to a medication). The mobile app submits reports and looks up regulatory-authority information, while the PIMS (Practice Information Management System, the clinic-facing web app) lists reports for an organisation and updates their status.","sidebar":"docs"},"apps/backend/routers/backend-api-appointment":{"id":"apps/backend/routers/backend-api-appointment","title":"Appointment API","description":"Covers the appointment lifecycle (request, reschedule, cancel, check-in, accept/reject). Routes under /mobile are called by the mobile app on behalf of a pet parent; routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-audit-trail":{"id":"apps/backend/routers/backend-api-audit-trail","title":"Audit Trail API","description":"Read-only endpoints for retrieving the audit trail (the history of recorded actions) for a companion or an appointment. Called by the PIMS (Practice Information Management System, the clinic-facing web app); both routes require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-authUserMobile":{"id":"apps/backend/routers/backend-api-authUserMobile","title":"Authusermobile API","description":"Handles user signup for the mobile app. The endpoint is guarded by the mobile auth middleware (requireMobileAuth) and creates the backend user record for an authenticated mobile account.","sidebar":"docs"},"apps/backend/routers/backend-api-availability":{"id":"apps/backend/routers/backend-api-availability","title":"Availability API","description":"Manages an organisation\'s scheduling availability: base (default) hours, weekly overrides, occupancy, and the computed final availability used when booking appointments. Called by the PIMS (Practice Information Management System, the clinic-facing web app); routes are scoped to an organisation by orgId.","sidebar":"docs"},"apps/backend/routers/backend-api-chat":{"id":"apps/backend/routers/backend-api-chat","title":"Chat API","description":"Provides messaging: chat tokens, appointment-linked sessions, and organisation direct/group chats. Routes under /mobile are called by the mobile app (pet parents); routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app) and additionally manage group membership.","sidebar":"docs"},"apps/backend/routers/backend-api-companion":{"id":"apps/backend/routers/backend-api-companion","title":"Companion API","description":"Manages companion (pet) records: create, read, update, delete, profile image uploads, and search. Routes without a prefix are called by the mobile app (pet parents); routes under /org are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-companion-organisation":{"id":"apps/backend/routers/backend-api-companion-organisation","title":"Companion Organisation API","description":"Manages the link between a companion (a pet) and an organisation (a clinic): linking, invites, approval, and revocation. Routes without a prefix are called by the mobile app (pet parents); routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-contact-us":{"id":"apps/backend/routers/backend-api-contact-us","title":"Contact Us API","description":"Handles \\"contact us\\" support requests. The mobile app submits a request (POST /contact); staff using the PIMS (Practice Information Management System, the clinic-facing web app) list requests and update their status.","sidebar":"docs"},"apps/backend/routers/backend-api-coparentInvite":{"id":"apps/backend/routers/backend-api-coparentInvite","title":"Coparentinvite API","description":"Handles co-parent invitations, letting a pet parent invite another person to share access to a companion (pet). Called by the mobile app; the /validate route is public (no auth) so an invite token can be checked before the invitee signs in.","sidebar":"docs"},"apps/backend/routers/backend-api-dashboard":{"id":"apps/backend/routers/backend-api-dashboard","title":"Dashboard API","description":"Read-only analytics endpoints (summary, appointment and revenue trends, leaderboards, inventory turnover) for an organisation\'s dashboard. Called by the PIMS (Practice Information Management System, the clinic-facing web app); every route requires organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-deviceToken":{"id":"apps/backend/routers/backend-api-deviceToken","title":"Devicetoken API","description":"Registers and unregisters push-notification device tokens. Called by the mobile app so the backend can deliver push notifications to a signed-in user\'s device.","sidebar":"docs"},"apps/backend/routers/backend-api-documenso":{"id":"apps/backend/routers/backend-api-documenso","title":"Documenso API","description":"Integrates with Documenso, an open-source document e-signature service. Called by the PIMS (Practice Information Management System, the clinic-facing web app) to obtain a signing redirect URL and to store an organisation\'s Documenso API key.","sidebar":"docs"},"apps/backend/routers/backend-api-document":{"id":"apps/backend/routers/backend-api-document","title":"Document API","description":"Manages companion (pet) documents: upload URLs, create, list, update, view/download, search, and delete. Routes under /mobile are called by the mobile app (pet parents); routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-expense":{"id":"apps/backend/routers/backend-api-expense","title":"Expense API","description":"Lets a pet parent track expenses recorded against a companion (pet), including per-companion listing and summaries. Called by the mobile app; all routes are guarded by the mobile auth middleware (requireMobileAuth).","sidebar":"docs"},"apps/backend/routers/backend-api-form":{"id":"apps/backend/routers/backend-api-form","title":"Form API","description":"Manages clinical and consent forms, form submissions, and signing, including SOAP notes (the Subjective, Objective, Assessment, Plan structure vets use to record a visit). Routes under /admin and the signing routes are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions; routes under /mobile and /public are called by the mobile app (pet parents).","sidebar":"docs"},"apps/backend/routers/backend-api-inventory":{"id":"apps/backend/routers/backend-api-inventory","title":"Inventory API","description":"Manages clinic inventory: items and batches, stock consumption and adjustments, vendors, custom meta-fields, and low-stock/expiry alerts. Called by the PIMS (Practice Information Management System, the clinic-facing web app); most routes require organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-invoice":{"id":"apps/backend/routers/backend-api-invoice","title":"Invoice API","description":"Covers invoices tied to appointments: listing them, adding charges, looking them up by payment intent, and creating Stripe checkout sessions. Routes under /mobile are called by the mobile app on behalf of a pet parent; the remaining routes are called by the PIMS (Practice Information Management System, the clinic-facing web app). See the Stripe API for the underlying payment endpoints.","sidebar":"docs"},"apps/backend/routers/backend-api-mobile.config":{"id":"apps/backend/routers/backend-api-mobile.config","title":"Mobile.Config API","description":"Serves runtime configuration (such as the current environment and app-update settings) that the mobile app fetches on startup. The single route is registered on this router\'s mount root rather than a named sub-path, so the endpoint generator lists none below.","sidebar":"docs"},"apps/backend/routers/backend-api-notification":{"id":"apps/backend/routers/backend-api-notification","title":"Notification API","description":"Lets the mobile app list a pet parent\'s notifications and mark one as seen. Both routes are called by the mobile app and authenticated with the pet parent\'s SuperTokens session (requireMobileAuth).","sidebar":"docs"},"apps/backend/routers/backend-api-observationTool":{"id":"apps/backend/routers/backend-api-observationTool","title":"Observationtool API","description":"Manages observation tools: reusable structured questionnaires (a definition plus its typed fields) that a pet parent fills in, producing a submission that can be linked to an appointment or task. Routes under /mobile are called by the mobile app on behalf of a pet parent; routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app), which additionally authors and manages the tool definitions.","sidebar":"docs"},"apps/backend/routers/backend-api-organisation-document":{"id":"apps/backend/routers/backend-api-organisation-document","title":"Organisation Document API","description":"Manages an organisation\'s documents and policies (upload, create, update, delete, list) plus policy upsert. The /pms routes are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions; the /mobile route lets the mobile app list the documents an organisation has published publicly.","sidebar":"docs"},"apps/backend/routers/backend-api-organisation-invite":{"id":"apps/backend/routers/backend-api-organisation-invite","title":"Organisation Invite API","description":"Lets an invited user act on organisation invites: accept or decline a specific invite by token, and list their own pending invites. Invites are created from the Organization API.","sidebar":"docs"},"apps/backend/routers/backend-api-organisation-room":{"id":"apps/backend/routers/backend-api-organisation-room","title":"Organisation Room API","description":"CRUD endpoints for an organisation\'s rooms (for example consultation or treatment rooms). Called by the PIMS (Practice Information Management System, the clinic-facing web app); every route requires organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-organisationRating":{"id":"apps/backend/routers/backend-api-organisationRating","title":"Organisationrating API","description":"Lets a pet parent rate an organisation and check whether they have already rated it. Both routes are called by the mobile app and authenticated with the pet parent\'s SuperTokens session (requireMobileAuth).","sidebar":"docs"},"apps/backend/routers/backend-api-organization":{"id":"apps/backend/routers/backend-api-organization","title":"Organization API","description":"Manages organisations (also referred to as businesses): nearby search, logo uploads, CRUD, and the creation and listing of organisation invites. The nearby-search routes are open or called by the mobile app; the CRUD and invite routes are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions. Invitees act on invites through the Organisation Invite API, and specialities are managed through the Speciality API.","sidebar":"docs"},"apps/backend/routers/backend-api-parent":{"id":"apps/backend/routers/backend-api-parent","title":"Parent API","description":"Manages parent (pet owner) records and profile-picture uploads, and lists a parent\'s companions (their pets). The mobile-app routes are authenticated with the pet parent\'s SuperTokens session (requireMobileAuth); the /pms routes are called by the PIMS (Practice Information Management System, the clinic-facing web app). See the Parent Companion API for links between co-parents.","sidebar":"docs"},"apps/backend/routers/backend-api-parent-companion":{"id":"apps/backend/routers/backend-api-parent-companion","title":"Parent Companion API","description":"Manages the links between parents (pet owners) and companions (the pets, also shown as animal, pet, or patient depending on the clinic\'s preference): listing links, updating a co-parent\'s permissions, promoting a co-parent to primary, and removing a co-parent. All routes are called by the mobile app and authenticated with the pet parent\'s SuperTokens session (requireMobileAuth). See the Parent API for parent records.","sidebar":"docs"},"apps/backend/routers/backend-api-service":{"id":"apps/backend/routers/backend-api-service","title":"Service API","description":"Lets clients discover the services organisations offer: search by service name and location, list an organisation\'s services, fetch a service\'s bookable slots, and remove a service.","sidebar":"docs"},"apps/backend/routers/backend-api-speciality":{"id":"apps/backend/routers/backend-api-speciality","title":"Speciality API","description":"CRUD endpoints for an organisation\'s specialities (the areas of veterinary practice it offers). Called by the PIMS (Practice Information Management System, the clinic-facing web app); every route requires organisation RBAC (role-based access control) permissions.","sidebar":"docs"},"apps/backend/routers/backend-api-stripe":{"id":"apps/backend/routers/backend-api-stripe","title":"Stripe API","description":"Wraps the Stripe payment integration: the incoming Stripe webhook, payment intents and checkout sessions, and Stripe Connect account onboarding plus subscription billing for organisations. The webhook is called by Stripe; the payment-intent routes are called by the mobile app; the /pms and /organisation routes are called by the PIMS (Practice Information Management System, the clinic-facing web app) and require organisation RBAC (role-based access control) permissions. See the Invoice API for the invoices these payments settle.","sidebar":"docs"},"apps/backend/routers/backend-api-task":{"id":"apps/backend/routers/backend-api-task","title":"Task API","description":"Manages tasks and the libraries and templates they are created from: creating, listing, updating, and changing the status of tasks. Routes under /mobile are called by the mobile app on behalf of a pet parent; routes under /pms are called by the PIMS (Practice Information Management System, the clinic-facing web app). See the Observation Tool API for submissions that can be linked to a task.","sidebar":"docs"},"apps/backend/routers/backend-api-user":{"id":"apps/backend/routers/backend-api-user","title":"User API","description":"Endpoints for a user account: creating, fetching, updating the name, and deleting a user. See the User Profile API for per-organisation profile details and the User Organization API for organisation memberships.","sidebar":"docs"},"apps/backend/routers/backend-api-user-organization":{"id":"apps/backend/routers/backend-api-user-organization","title":"User Organization API","description":"Manages the mappings between users and the organisations they belong to: listing a user\'s memberships, listing the members of an organisation, and updating or removing a mapping. See the User API and Organization API for the records these mappings connect.","sidebar":"docs"},"apps/backend/routers/backend-api-user-profile":{"id":"apps/backend/routers/backend-api-user-profile","title":"User Profile API","description":"Manages a user\'s profile within a specific organisation (create, update, fetch, and profile-picture uploads). Called by the PIMS (Practice Information Management System, the clinic-facing web app). See the User API for the underlying user account.","sidebar":"docs"},"apps/frontend-app":{"id":"apps/frontend-app","title":"Frontend App README","description":"(Source: apps/frontend/README.md)","sidebar":"docs"},"apps/mobile-app":{"id":"apps/mobile-app","title":"Mobile App README","description":"(Source: apps/mobileAppYC/README.md)","sidebar":"docs"},"guides/backend-chat-implementation":{"id":"guides/backend-chat-implementation","title":"Backend Chat Implementation","description":"(Source: Guides/BACKENDCHATIMPLEMENTATION.md)","sidebar":"docs"},"guides/notification-setup-guide":{"id":"guides/notification-setup-guide","title":"Notification Setup Guide","description":"(Mirrored from docs/guide/NOTIFICATIONSETUPGUIDE.md \u2014 do not edit here; update the canonical file and re-sync.)","sidebar":"docs"},"openapi":{"id":"openapi","title":"OpenAPI Reference","description":"OpenAPI is the standard, machine-readable format for describing a REST API (its endpoints, parameters, and response shapes). This page renders the Yosemite Crew backend OpenAPI spec as a browsable reference. The viewer is Redoc, which is read-only: it has no \\"try it\\" console, so requests are not sent from this page. for a per-router breakdown of the same API, see the Backend API Index. The spec is located at apps/dev-docs/static/openapi.yaml.","sidebar":"docs"},"overview":{"id":"overview","title":"Yosemite Crew Overview","description":"(Source: README.md)","sidebar":"docs"},"policies/code-of-conduct":{"id":"policies/code-of-conduct","title":"Code of Conduct","description":"(Source: CODEOFCONDUCT.md)","sidebar":"docs"},"policies/contributing":{"id":"policies/contributing","title":"Contributing Guide","description":"(Source: CONTRIBUTING.md)","sidebar":"docs"},"policies/security":{"id":"policies/security","title":"Security Policy","description":"(Source: SECURITY.md)","sidebar":"docs"},"ui-system/component-taxonomy":{"id":"ui-system/component-taxonomy","title":"Component Taxonomy","description":"How components are classified, what categories exist, and how to decide where new UI belongs.","sidebar":"docs"},"ui-system/contribution-guide":{"id":"ui-system/contribution-guide","title":"Contribution Guide","description":"Rules for adding, modifying, and reviewing UI components \u2014 for humans and AI agents.","sidebar":"docs"},"ui-system/design-tokens":{"id":"ui-system/design-tokens","title":"Design Tokens","description":"How to read, use, and extend the shared semantic token package.","sidebar":"docs"},"ui-system/overview":{"id":"ui-system/overview","title":"UI System Overview","description":"How the Yosemite Crew UI platform is structured, what it owns, and how to use it.","sidebar":"docs"},"ui-system/validation-matrix":{"id":"ui-system/validation-matrix","title":"Validation Matrix","description":"GxP-ready validation expectations for UI component classes.","sidebar":"docs"}}}}')}}]);